options.getOption:
// Los tramos con incidencia por cuarto de hora: cuántos tuvieron como peor
// estado del cuarto denso, congestionado o cortado, apilados en los colores
// del mapa. Arrastrar sobre las barras elige un tramo de tiempo, escrito en
// dos variables (FROM y TO, en UTC): el mapa, la tabla y la gráfica de
// estados pasan a mostrar el peor estado de cada tramo en ese tiempo, en
// vez del de ahora. La goma de la esquina lo quita.
// @constants begin
const FROM = 'slot_from';
const TO = 'slot_to';
const STEP_MS = 15 * 60 * 1000;
const SERIES = [
  ['denso', 'Denso', '#fdae61'],
  ['congestionado', 'Congestionado', '#d73027'],
  ['cortado', 'Cortado', '#7b0d1e'],
];
const TZ = 'Europe/Madrid';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const times = col('t').map(Number);
const hhmm = new Intl.DateTimeFormat('es-ES', { timeZone: TZ, hour: '2-digit', minute: '2-digit' });
const day = new Intl.DateTimeFormat('es-ES', { timeZone: TZ, weekday: 'short', day: 'numeric' });
const dayOf = (t) => day.format(new Date(t));
// A category per quarter hour: stacking works on a category axis, not on a
// time axis. The label carries the day where it changes.
const labels = times.map((t, i) => (i === 0 || dayOf(t) !== dayOf(times[i - 1]) ? `${dayOf(t)} ${hhmm.format(new Date(t))}` : hhmm.format(new Date(t))));

// On a category axis a brush range is a pair of indices.
const snap = (range) => {
  const lo = Math.max(0, Math.round(range[0]));
  const hi = Math.min(times.length - 1, Math.max(lo, Math.round(range[1])));
  return [lo, hi];
};
const drawBrush = (range) =>
  chart.dispatchAction({ type: 'brush', areas: range ? [{ brushType: 'lineX', xAxisIndex: 0, coordRange: range }] : [] });
const publish = (range) => {
  location.partial(
    {
      ['var-' + FROM]: range ? new Date(times[range[0]]).toISOString() : '',
      ['var-' + TO]: range ? new Date(times[range[1]] + STEP_MS).toISOString() : '',
    },
    true,
  );
};

chart.off('brushEnd');
chart.off('brush');
chart.on('brushEnd', (event) => {
  const area = event.areas[0];
  if (!area || !area.coordRange || !times.length) {
    publish(undefined);
    return;
  }
  const range = snap(area.coordRange);
  publish(range);
  setTimeout(() => drawBrush(range), 0);
});
chart.on('brush', (event) => {
  if (event.command === 'clear') {
    publish(undefined);
  }
});

// Every redraw wipes the brush: draw it back from the variables, named here
// as ${slot_from} and ${slot_to} so the panel redraws when they change.
const from = Date.parse(context.grafana.replaceVariables('${' + FROM + '}'));
const to = Date.parse(context.grafana.replaceVariables('${' + TO + '}'));
setTimeout(() => {
  chart.dispatchAction({ type: 'takeGlobalCursor', key: 'brush', brushOption: { brushType: 'lineX', brushMode: 'single' } });
  if (Number.isFinite(from) && Number.isFinite(to) && times.length) {
    const lo = times.findIndex((t) => t >= from);
    const after = times.findIndex((t) => t >= to);
    const hi = (after === -1 ? times.length : after) - 1;
    if (lo !== -1 && hi >= lo) {
      drawBrush([lo, hi]);
    }
  }
}, 0);

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 16, top: 30, bottom: 8, containLabel: true },
  legend: { top: 0, left: 'center', textStyle: { color: muted }, itemWidth: 12, itemHeight: 10 },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const i = items[0].dataIndex;
      const t = new Date(times[i]);
      const rows = items.map((it) => `${it.marker}${it.seriesName}: <b>${it.value}</b>`).join('<br/>');
      return `${dayOf(times[i])} ${hhmm.format(t)}–${hhmm.format(new Date(times[i] + STEP_MS))}<br/>${rows}`;
    },
  },
  toolbox: {
    right: 8,
    top: 0,
    itemSize: 14,
    feature: { brush: { type: ['lineX', 'clear'], title: { lineX: 'Elegir un tramo de tiempo', clear: 'Quitar el filtro' } } },
  },
  brush: {
    xAxisIndex: 0,
    brushType: 'lineX',
    brushMode: 'single',
    transformable: true,
    brushStyle: { color: 'rgba(128, 128, 128, 0.12)', borderColor: muted, borderWidth: 1 },
    outOfBrush: { colorAlpha: 0.25 },
  },
  xAxis: { type: 'category', data: labels, axisTick: { alignWithLabel: true }, axisLabel: { color: muted, fontSize: 11 } },
  yAxis: { type: 'value', minInterval: 1, axisLabel: { color: muted }, splitLine: { lineStyle: { opacity: 0.15 } } },
  series: SERIES.map(([key, name, color]) => ({
    name,
    type: 'bar',
    stack: 'incidencias',
    barWidth: '85%',
    data: col(key).map((v) => (v == null ? null : Number(v))),
    itemStyle: { color },
  })),
};

