options.getOption:
// Los tramos por estado del tráfico, en los colores del mapa: el estado de
// ahora o, con un tramo de tiempo elegido en la gráfica de incidencias, el
// peor de ese tramo. Un clic en una barra filtra el mapa y la tabla por ese
// estado; otro clic en la misma lo quita. El eje es logarítmico: casi todos
// los tramos están fluidos, y con un eje lineal las incidencias no se verían.
// @constants begin
const VAR = 'state';
const ORDER = ['Fluido', 'Denso', 'Congestionado', 'Cortado', 'Sin datos'];
const COLORS = { Fluido: '#1a9850', Denso: '#fdae61', Congestionado: '#d73027', Cortado: '#7b0d1e', 'Sin datos': '#9e9e9e' };
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
const labels = col('state_label');
const counts = col('n').map(Number);
const byLabel = Object.fromEntries(labels.map((l, i) => [l, counts[i]]));
// ECharts draws a category axis bottom up: reversed, the first state is on top.
const states = ORDER.slice().reverse();
const values = states.map((s) => byLabel[s] ?? 0);
// Read as '${state}', and written out here so the panel redraws when it changes.
const picked = context.grafana.replaceVariables('${' + VAR + '}');

chart.off('click');
chart.on('click', (event) => {
  const id = states[event.dataIndex];
  const same = id === context.grafana.replaceVariables('${' + VAR + '}');
  location.partial({ ['var-' + VAR]: same ? '' : id }, true);
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 44, top: 6, bottom: 6, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => `${items[0].name}: <b>${values[items[0].dataIndex]}</b> tramos`,
  },
  xAxis: { type: 'log', min: 0.5, axisLabel: { show: false }, splitLine: { show: false } },
  yAxis: { type: 'category', data: states, axisTick: { show: false }, axisLabel: { color: text, fontSize: 11 } },
  series: [
    {
      type: 'bar',
      barWidth: '70%',
      cursor: 'pointer',
      data: values.map((v, i) => ({
        value: v === 0 ? null : v,
        itemStyle: { color: COLORS[states[i]], opacity: picked && picked !== states[i] ? 0.35 : 1, borderRadius: [0, 4, 4, 0] },
      })),
      label: { show: true, position: 'right', color: muted, fontSize: 11, formatter: (p) => p.value },
    },
  ],
};

