options.getOption:
// Las estaciones por su última lectura de la medida elegida, en los seis
// colores del mapa (cada lectura, por su sextil entre las del último día,
// como reparte el mapa su escala). Un clic en una barra elige la estación,
// como un clic en el mapa; otro clic en la misma la suelta.
// @constants begin
const VAR = 'station';
const COLORS = ['#5794F2', '#8AB8FF', '#FADE2A', '#FF9830', '#F2495C', '#E02F44'];
const METRIC = 'metric';
// @constants end

const chart = context.panel.chart;
const location = context.grafana.locationService;
const theme = context.grafana.theme;
const muted = theme.colors.text.secondary;
const text = theme.colors.text.primary;

const frame = context.panel.data.series.find((f) => f.refId === 'A');
const col = (name) => (frame ? Array.from(frame.fields.find((f) => f.name === name)?.values ?? []) : []);
// ECharts draws a category axis bottom up: reversed, the highest is on top.
const ids = col('station').reverse();
const names = col('name').reverse();
const kinds = col('kind').reverse();
const values = col('value').map(Number).reverse();
const buckets = col('bucket').map(Number).reverse();
// The measure's label is "Name (unit)": the unit goes on the axis.
const label = context.grafana.replaceVariables('${' + METRIC + ':text}');
const unit = (label.match(/\(([^)]*)\)/) || [])[1] || '';
// Read as '${station}' and written out here so the panel redraws when it changes.
const picked = context.grafana.replaceVariables('${' + VAR + '}');

chart.off('click');
chart.on('click', (event) => {
  const id = ids[event.dataIndex];
  const same = id === context.grafana.replaceVariables('${' + VAR + '}');
  location.partial({ ['var-' + VAR]: same ? '' : id }, true);
});

return {
  animation: false,
  backgroundColor: 'transparent',
  grid: { left: 8, right: 44, top: 26, bottom: 8, containLabel: true },
  tooltip: {
    trigger: 'axis',
    axisPointer: { type: 'shadow' },
    formatter: (items) => {
      const i = items[0].dataIndex;
      return `<b>${names[i]}</b> · ${kinds[i]}<br/>${label}: <b>${values[i]}</b>`;
    },
  },
  xAxis: { type: 'value', name: unit, nameLocation: 'end', nameTextStyle: { color: muted }, axisLabel: { color: muted }, splitLine: { lineStyle: { opacity: 0.15 } } },
  yAxis: { type: 'category', data: names, axisTick: { show: false }, axisLabel: { color: text, fontSize: 11 } },
  series: [
    {
      type: 'bar',
      barWidth: '70%',
      cursor: 'pointer',
      data: values.map((v, i) => ({
        value: v,
        itemStyle: { color: COLORS[Math.min(5, Math.max(0, buckets[i]))], opacity: picked && picked !== ids[i] ? 0.35 : 1, borderRadius: [0, 4, 4, 0] },
      })),
      label: { show: true, position: 'right', color: muted, fontSize: 11, formatter: (p) => p.value },
    },
  ],
};

